function translateObject(value,dict,key=''){
 if(key==='aliases')return structuredClone(value);
 if(typeof value==='string')return dict[value]??value;
 if(Array.isArray(value))return value.map(v=>translateObject(v,dict));
 if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,translateObject(v,dict,k)]));
 return value;
}
const languageViews={zh:{story:translateObject(storyOriginal,ZH_TEXT),notes:translateObject(notesOriginal,ZH_TEXT),people:translateObject(peopleOriginal,ZH_TEXT),chapters:translateObject(chaptersOriginal,ZH_TEXT)},en:{story:translateObject(storyOriginal,EN_TEXT),notes:translateObject(notesOriginal,EN_TEXT),people:translateObject(peopleOriginal,EN_TEXT),chapters:translateObject(chaptersOriginal,EN_TEXT)}};
