function t(key,params={}){let text=UI_TEXT[key]?.[language==='en'?1:0]??key;for(const [k,v]of Object.entries(params))text=text.replaceAll('{'+k+'}',String(v));return text;}
function numberLabel(n){return language==='en'?String(n):['零','一','二','三','四','五','六','七','八','九','十'][n]||String(n);}
function recordedText(text){return historyTranslations[language][text]??text;}
function setLanguage(next){
 language=next==='en'?'en':'zh';const view=languageViews[language];
 for(const [id,n]of Object.entries(view.story))STORY[id]=structuredClone(n);
 for(const [id,n]of Object.entries(view.notes))NOTES[id]=structuredClone(n);
 PEOPLE.splice(0,PEOPLE.length,...structuredClone(view.people));Object.assign(CHAPTERS,view.chapters);
 try{localStorage.setItem('vicious-cycle-language-v1',language);}catch{}
}
